def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full-length separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # The separator color is shared by the full-length lines.
    colors = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    sep = max(set(colors), key=colors.count)

    row_bounds = [-1] + [r for r in sep_rows if grid[r][0] == sep] + [h]
    col_bounds = [-1] + [c for c in sep_cols if grid[0][c] == sep] + [w]
    row_rooms = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_rooms = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    interior = [
        grid[r][c]
        for r0, r1 in row_rooms for c0, c1 in col_rooms
        for r in range(r0, r1) for c in range(c0, c1)
    ]
    bg = max(set(interior), key=interior.count)

    # Use the room containing the non-background pattern as the repeating tile.
    source = None
    for r0, r1 in row_rooms:
        for c0, c1 in col_rooms:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                source = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
                break
        if source is not None:
            break

    out = [row[:] for row in grid]
    if source is not None:
        for r0, r1 in row_rooms:
            for c0, c1 in col_rooms:
                for dr, r in enumerate(range(r0, r1)):
                    for dc, c in enumerate(range(c0, c1)):
                        out[r][c] = source[dr][dc]
    return out
